import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import Editor from '@monaco-editor/react';
import axios from 'axios';

const AssignmentAttempt = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const [assignment, setAssignment] = useState(null);
    const [query, setQuery] = useState('');
    const [results, setResults] = useState(null);
    const [errorMsg, setErrorMsg] = useState(null);
    const [hint, setHint] = useState('');
    const [loadingHint, setLoadingHint] = useState(false);
    const [executing, setExecuting] = useState(false);

    useEffect(() => {
        const fetchAssignment = async () => {
            try {
                const res = await axios.get(`http://localhost:5000/api/assignments/${id}`);
                setAssignment(res.data);
            } catch (err) {
                console.error(err);
                setErrorMsg("Failed to load assignment data.");
            }
        };
        fetchAssignment();
    }, [id]);

    const handleExecute = async () => {
        setExecuting(true);
        setErrorMsg(null);
        setResults(null);
        setHint('');

        try {
            const res = await axios.post('http://localhost:5000/api/execute', { 
                query,
                assignmentId: id 
            });
            setResults(res.data);
        } catch (err) {
            setErrorMsg(err.response?.data?.error || "Execution failed.");
        } finally {
            setExecuting(false);
        }
    };

    const handleGetHint = async () => {
        if (!query.trim()) {
            setErrorMsg("Please write some SQL first before asking for a hint.");
            return;
        }

        setLoadingHint(true);
        try {
            const res = await axios.post('http://localhost:5000/api/hints', {
                assignmentId: id,
                userQuery: query
            });
            setHint(res.data.hint);
        } catch (err) {
            setErrorMsg("Failed to generate hint.");
        } finally {
            setLoadingHint(false);
        }
    };

    if (!assignment) return <div className="loader">Loading workspace...</div>;

    return (
        <div className="workspace">
            {/* Left Panel: Assignment Details & Schema */}
            <div className="workspace__left">
                <button className="btn--primary" style={{width: 'fit-content'}} onClick={() => navigate('/')}>
                    &larr; Back to Listings
                </button>
                
                <div className="workspace__panel">
                    <div className="workspace__panel-header">
                        <h3>Problem Statement</h3>
                        <span className={`assignment-card__diff assignment-card__diff--${assignment.difficulty.toLowerCase()}`}>
                            {assignment.difficulty}
                        </span>
                    </div>
                    <div className="workspace__panel-content" style={{padding: '0 5px'}}>
                        <h4 style={{marginBottom: '10px'}}>{assignment.title}</h4>
                        <p>{assignment.description}</p>
                        
                        <h4 style={{marginTop: '20px', marginBottom: '10px'}}>Available Tables</h4>
                        {assignment.expectedTables?.map((tbl, idx) => (
                            <div key={idx} style={{marginBottom: '15px', padding: '10px', background: '#ecf0f1', borderRadius: '4px'}}>
                                <strong>{tbl.tableName}</strong>
                                <p style={{fontSize: '0.85rem', color: '#555', margin: '5px 0'}}>{tbl.schemaDescription}</p>
                                {/* We can render standard table here just for visual sample if they have sample data */}
                                {tbl.sampleData && tbl.sampleData.length > 0 && (
                                   <table className="results-table" style={{marginTop: '10px'}}>
                                       <thead>
                                           <tr>
                                               {Object.keys(tbl.sampleData[0]).map(k => <th key={k}>{k}</th>)}
                                           </tr>
                                       </thead>
                                       <tbody>
                                           {tbl.sampleData.map((row, i) => (
                                               <tr key={i}>
                                                   {Object.values(row).map((val, cellIdx) => <td key={cellIdx}>{val}</td>)}
                                               </tr>
                                           ))}
                                       </tbody>
                                   </table>
                                )}
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* Right Panel: Editor & Results */}
            <div className="workspace__right">
                <div className="workspace__panel">
                    <div className="workspace__panel-header">
                        <h3>SQL Editor</h3>
                        <div style={{display: 'flex', gap: '10px'}}>
                            <button 
                                className="btn--accent" 
                                onClick={handleGetHint} 
                                disabled={loadingHint || executing}
                            >
                                {loadingHint ? "Thinking..." : "Get Hint"}
                            </button>
                            <button 
                                className="btn--success" 
                                onClick={handleExecute} 
                                disabled={executing || !query.trim()}
                            >
                                {executing ? "Executing..." : "Run Query"}
                            </button>
                        </div>
                    </div>
                    
                    <div className="workspace__panel-content workspace__panel-content--editor">
                        <Editor
                            height="100%"
                            defaultLanguage="sql"
                            value={query}
                            onChange={(val) => setQuery(val)}
                            theme="vs-dark"
                            options={{
                                minimap: { enabled: false },
                                fontSize: 14,
                                wordWrap: 'on'
                            }}
                        />
                    </div>
                </div>

                {/* Output Panel */}
                <div className="workspace__panel" style={{flex: 0.8}}>
                    <div className="workspace__panel-header">
                        <h3>Execution Results</h3>
                    </div>
                    <div className="workspace__panel-content">
                        {errorMsg && <div className="error-msg">{errorMsg}</div>}
                        {hint && <div className="hint-box">­ƒÆí <strong>AI Hint:</strong> <br/>{hint}</div>}
                        
                        {results && (
                           <div style={{marginTop: '10px'}}>
                                {results.isCorrect !== undefined && (
                                    <div style={{
                                        padding: '10px', 
                                        borderRadius: '4px', 
                                        marginBottom: '10px',
                                        backgroundColor: results.isCorrect ? '#e8f8f5' : '#fdedec',
                                        borderLeft: `4px solid ${results.isCorrect ? '#2ecc71' : '#e74c3c'}`,
                                        color: results.isCorrect ? '#1e8449' : '#c0392b'
                                    }}>
                                        <strong>{results.isCorrect ? 'Ô£à Correct!' : 'ÔØî Incorrect Data.'}</strong>
                                        {results.isCorrect 
                                            ? ' Your query returns the exact expected results.'
                                            : ' Your query executed successfully, but the resulting data does not match the expected answer. Keep trying!'}
                                    </div>
                                )}
                                <p style={{marginBottom: '10px', fontSize: '0.9rem', color: '#2ecc71'}}>
                                    Query Executed Successfully! Rows returned: {results.rowCount}
                                </p>
                               <div style={{overflowX: 'auto'}}>
                                   <table className="results-table">
                                       <thead>
                                           <tr>
                                               {results.columns?.map(col => <th key={col}>{col}</th>)}
                                           </tr>
                                       </thead>
                                       <tbody>
                                           {results.rows?.map((row, idx) => (
                                               <tr key={idx}>
                                                   {results.columns.map(col => <td key={col}>{row[col]}</td>)}
                                               </tr>
                                           ))}
                                       </tbody>
                                   </table>
                               </div>
                           </div>
                        )}

                        {!errorMsg && !results && !hint && (
                            <p style={{color: '#7f8c8d', fontStyle: 'italic', textAlign: 'center', marginTop: '20px'}}>
                                Run a query to see results or get a hint.
                            </p>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default AssignmentAttempt;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const Home = () => {
    const [assignments, setAssignments] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const navigate = useNavigate();

    useEffect(() => {
        const fetchAssignments = async () => {
            try {
                // If backend isn't ready, we fallback to an empty array
                const res = await axios.get('http://localhost:5000/api/assignments');
                setAssignments(res.data);
                setLoading(false);
            } catch (err) {
                console.error("Failed to fetch assignments.", err);
                setError("Failed to connect to backend. Please ensure the server is running.");
                setLoading(false);
            }
        };
        fetchAssignments();
    }, []);

    if (loading) return <div className="loader">Loading assignments...</div>;
    
    // Also handling empty states gracefully
    if (error && assignments.length === 0) {
      return (
        <div style={{textAlign: 'center', marginTop: '2rem'}}>
          <p className="error-msg">{error}</p>
          <div style={{marginTop: '1rem'}}>
            <p><strong>Note:</strong> Make sure you have started your MongoDB server and seeded the data using <code>node src/seed.js</code> in the backend folder.</p>
          </div>
        </div>
      );
    }

    return (
        <div>
            <h2 style={{ marginBottom: '1rem', color: '#2c3e50' }}>Available Assignments</h2>
            
            {assignments.length === 0 ? (
                <p>No assignments found. Please seed the database.</p>
            ) : (
                <div className="assignment-list">
                    {assignments.map(assign => (
                        <div key={assign._id} className="assignment-card">
                            <div className="assignment-card__header">
                                <span className={`assignment-card__diff assignment-card__diff--${assign.difficulty.toLowerCase()}`}>
                                    {assign.difficulty}
                                </span>
                            </div>
                            <h3 className="assignment-card__title">{assign.title}</h3>
                            <p>{assign.description}</p>
                            <button 
                                className="btn--primary"
                                onClick={() => navigate(`/assignment/${assign._id}`)}
                                style={{marginTop: 'auto'}}
                            >
                                Attempt Assignment
                            </button>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
};

export default Home;
